{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.horizontal_sales_categories AS ( with base_product as ( select sku_group, product_tags, category, original_price, current_slashed_price, cost_price, occassion as occassion_new, print_design, collar_mapped as collar_new, material_mapped as material_new, sleeves_type as sleeve_type, fit, color, closure, style, sku_class from snitch_db.maplemonk.base_product qualify row_number() over (partition by upper(trim(sku_group)) order by product_tags desc) = 1 ), shopify_sales AS ( SELECT order_timestamp::date AS Date, \'Shopify\' AS type, upper(trim(a.sku_group)) as sku_group, case when SIZE = \'XS\' OR SIZE = \'28\' then \'XS\' WHEN SIZE = \'S\' OR SIZE = \'30\' THEN \'S\' WHEN SIZE = \'M\' OR SIZE = \'32\' THEN \'M\' WHEN SIZE = \'M\' OR SIZE = \'32\' THEN \'M\' WHEN SIZE = \'L\' OR SIZE = \'34\' THEN \'L\' WHEN SIZE = \'XL\' OR SIZE = \'36\' THEN \'XL\' when SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN \'XXL\' WHEN SIZE = \'3XL\' OR SIZE = \'40\' THEN \'3XL\' WHEN SIZE = \'4XL\' OR SIZE = \'42\' then \'4XL\' WHEN SIZE = \'5XL\' OR SIZE = \'44\' then \'5XL\' WHEN SIZE = \'6XL\' OR SIZE = \'46\' THEN \'6XL\' WHEN SIZE = \'7XL\' OR SIZE = \'48\' THEN \'7XL\' WHEN SIZE = \'8XL\' OR SIZE = \'48\' THEN \'8XL\' end as size, b.category as category, b.product_tags as product_tags, b.original_price as price, b.cost_price, case when lower(tags) like \'%snitch_web%\' then \'web2\' when webshopney in (\'Shopney\',\'Appbrew\') then \'app\' when lower(webshopney) = \'snitch_ios\' and lower(tags) = \'snitch_ios\' then \'App2_IOS\' when lower(webshopney) = \'snitch_ios\' and lower(tags) != \'snitch_ios\' then \'App2_Android\' when lower(webshopney) = \'web\' then \'Web\' else \'App\' end as channel, SUM(NULLIF(gross_sales, 0)) AS gross_sales, SUM(NULLIF(quantity, 0)) AS gross_quantity, SUM( CASE WHEN lower(trim(payment_channel)) = \'cod\' and lower(discount_code) not like \'%snitch_rms%\' THEN (quantity)*(b.original_price) - (gross_sales-100) when lower(discount_code) not like \'%snitch_rms%\' then (quantity)*(b.original_price) - (gross_sales) else ((quantity)*(b.original_price) - coupon_discount - gross_sales) END ) AS discount_amount FROM snitch_db.maplemonk.fact_items_snitch a LEFT JOIN base_product b ON a.sku_group = b.sku_group WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') and gross_sales != 0 and lower(tags) not like \'%creator%\' and order_status = \'Shopify_Processed\' GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9 ), all_sales_data AS ( SELECT order_date, sku, case when left(sku_group,2) in (\'BP\',\'SN\') then sku else sku_group end as sku_group, CASE WHEN TRIM(UPPER(marketPlace_mapped)) IN (\'NYKAA.COM\', \'NYKAA_FASHION\') THEN \'NYKAA\' ELSE TRIM(UPPER(marketPlace_mapped)) END AS channel, shipping_quantity AS quantity, selling_price, discount, new_customer_flag FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate WHERE TRIM(UPPER(marketPlace_mapped)) IN (\'MYNTRA\', \'NYKAA.COM\', \'NYKAA_FASHION\', \'AMAZON\', \'FLIPKART\', \'AJIO\') AND ADDRESS_LINE_1 != \'FLIPKART_B2B_CUSTOM\' ), marketplace_data AS ( SELECT CAST(a.order_date AS DATE) AS Date, \'Marketplace\' AS type, upper(trim(a.sku_group)) as sku_group, case when upper(split_part(a.sku,\'-\',-1)) = \'XS\' OR upper(split_part(a.sku,\'-\',-1)) = \'28\' then \'XS\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'S\' OR upper(split_part(a.sku,\'-\',-1)) = \'30\' THEN \'S\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'M\' OR upper(split_part(a.sku,\'-\',-1)) = \'32\' THEN \'M\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'L\' OR upper(split_part(a.sku,\'-\',-1)) = \'34\' THEN \'L\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'36\' THEN \'XL\' when upper(split_part(a.sku,\'-\',-1)) IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN \'XXL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'3XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'40\' THEN \'3XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'4XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'42\' then \'4XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'5XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'44\' then \'5XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'6XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'46\' THEN \'6XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'7XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'48\' THEN \'7XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'8XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'48\' THEN \'8XL\' end as size, b.category as category, b.product_tags as product_tags, b.original_price as price, b.cost_price, a.channel, SUM(NULLIF(a.selling_price, 0)) AS gross_sales, SUM(NULLIF(a.quantity, 0)) AS gross_quantity, case when LOWER(a.channel) = \'ajio\' then SUM(NULLIF((b.original_price * a.quantity) - a.selling_price * 1.45, 0)) else SUM(NULLIF((b.original_price * a.quantity) - a.selling_price, 0)) end AS discount_amount FROM all_sales_data a LEFT JOIN base_product b ON upper(trim(a.sku_group)) = b.sku_group WHERE a.quantity > 0 GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9 ), stores_data AS ( SELECT order_date AS Date, \'Store\' AS type, upper(trim(a.sku_group)) as sku_group, case when upper(split_part(a.sku,\'-\',-1)) = \'XS\' OR upper(split_part(a.sku,\'-\',-1)) = \'28\' then \'XS\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'S\' OR upper(split_part(a.sku,\'-\',-1)) = \'30\' THEN \'S\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'M\' OR upper(split_part(a.sku,\'-\',-1)) = \'32\' THEN \'M\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'M\' OR upper(split_part(a.sku,\'-\',-1)) = \'32\' THEN \'M\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'L\' OR upper(split_part(a.sku,\'-\',-1)) = \'34\' THEN \'L\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'36\' THEN \'XL\' when upper(split_part(a.sku,\'-\',-1)) IN (\'XXL\', \'XXl\', \'2XL\', \'38\') THEN \'XXL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'3XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'40\' THEN \'3XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'4XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'42\' then \'4XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'5XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'44\' then \'5XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'6XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'46\' THEN \'6XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'7XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'48\' THEN \'7XL\' WHEN upper(split_part(a.sku,\'-\',-1)) = \'8XL\' OR upper(split_part(a.sku,\'-\',-1)) = \'48\' THEN \'8XL\' end as size, b.category as category, b.product_tags as product_tags, b.original_price as price, b.cost_price, MARKETPLACE_MAPPED AS channel, SUM(NULLIF(selling_price, 0)) AS gross_sales, SUM(NULLIF(shipping_quantity, 0)) AS gross_quantity, sum(shipping_quantity*b.original_price - selling_price) as discount_amount FROM snitch_db.maplemonk.STORE_fact_items_offline a left join base_product b on a.sku_group = b.sku_group where lower(a.sku_group) not like \'cb%\' AND marketplace_mapped not in (\'SNITCH - WH - B2B\', \'SNITCH - SNITCH X\', \'SNITCH - WH - M P\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - WH - U.P\', \'SNITCH - WH - NORTH\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - YELHANKA\' , \'SNITCH - WH - EMIZA\', \'SNITCH - WH - YELHANKA 2\' ) and lower(a.sku_group) not like \'cb%\' and a.doc_prefix not in (\'OMS\',\'QCOM\') GROUP BY 1, 2, 3, 4, 5, 6, 7, 8, 9 ), main_data2 as ( select * from shopify_sales union all select * from marketplace_data union all select * from stores_data ), sku_group_distinct as ( select a.*, b.occassion_new, b.print_design, b.collar_new, b.material_new, b.sleeve_type, b.fit, b.color, b.closure, b.style, b.sku_class from main_data2 a left join base_product b on a.sku_group = b.sku_group ), unique_shopify as ( select distinct date, sku_group, 1 as shopify_unique from main_data2 where type = \'Shopify\' and gross_quantity > 0 ), unique_store as ( select distinct date, sku_group, 1 as store_unique from main_data2 where type = \'Store\' and gross_quantity > 0 ), images as ( SELECT LEFT(variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION(\'-\' IN REVERSE(variant.value:sku::STRING))) AS sku_group, image.value:\"preview\":\"image\":\"url\"::string AS image_url FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => parse_json(t.media)) AS image, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) AS variant, WHERE image.value:\"mediaContentType\"::string = \'IMAGE\' qualify ROW_NUMBER() OVER (PARTITION BY t.id ORDER BY image.index) = 1 ) select a.*, case when shopify_unique = 1 AND store_unique = 1 THEN \'SHOPIFY-STORE\' WHEN shopify_unique = 1 THEN \'SHOPIFY\' WHEN STORE_unique = 1 THEN \'STORE\' else null end as store_shopify_common, d.image_url from sku_group_distinct a left join unique_shopify b on a.date = b.date and a.sku_group = b.sku_group left join unique_store c on a.date = c.date and a.sku_group = c.sku_group left join images d on a.sku_group = d.sku_group ); create or replace table snitch_db.maplemonk.cotton_sales_inv_mix as with sales as ( select date as order_date, sum(case when lower(material_new) like \'%cotton%\' then gross_quantity end) as cotton_qty, sum(gross_quantity) as total_quant from snitch_db.maplemonk.horizontal_sales_categories group by 1 ), cotton_sku as ( select sku_group from snitch_db.maplemonk.metafields_data where lower(material_new) like \'%cotton%\' ), inv as ( select date as order_date, sum(case when sku_group in (select sku_group from cotton_sku) then total_inventory end) as cotton_inv, sum(total_inventory) as total_inv from snitch_db.maplemonk.cut_size_analysis group by 1 ) select a.*, b.cotton_inv, b.total_inv from sales a left join inv b on a.order_date = b.order_date ;",
